alter table public.tasks add column if not exists priority text not null default 'normal'; do $$ begin if not exists ( select 1 from pg_constraint where conrelid = to_regclass('public.tasks') and conname = 'tasks_priority_check' ) then alter table public.tasks add constraint tasks_priority_check check (priority in ('urgent', 'high', 'normal', 'low')); end if; end $$; create index if not exists tasks_open_priority on public.tasks (priority, due_date) where not done;
